//! Reproduces C++ `std::ostream << double` default formatting, i.e. printf's
//! `%g` with the default precision of 6 significant digits (trailing zeros
//! stripped, scientific notation outside the [-4, 6) exponent window).

/// Format an `f32` exactly as C++ `std::cout` would with default flags.
pub fn fmt_g(value: f32) -> String {
    let v = value as f64;

    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }

    const P: i32 = 6; // default precision: 6 significant digits

    // Round to P significant digits in scientific form to learn the decimal
    // exponent of the *converted* value, as %g prescribes.
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').expect("scientific format always contains 'e'");
    let exp: i32 = sci[epos + 1..].parse().expect("valid exponent");

    if exp < -4 || exp >= P {
        // Scientific notation: strip trailing zeros from the mantissa and
        // emit the exponent with a sign and at least two digits (e-06).
        let mut mant = sci[..epos].to_string();
        if mant.contains('.') {
            while mant.ends_with('0') {
                mant.pop();
            }
            if mant.ends_with('.') {
                mant.pop();
            }
        }
        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        // Fixed notation with P - 1 - exp fractional digits, zeros stripped.
        let prec = (P - 1 - exp) as usize;
        let mut s = format!("{:.*}", prec, v);
        if s.contains('.') {
            while s.ends_with('0') {
                s.pop();
            }
            if s.ends_with('.') {
                s.pop();
            }
        }
        s
    }
}

