use colorspace::color::{ColorConverter, Yuv};
use colorspace::fmt::fmt_g;

/// Mimics C++ `std::stof`: skips leading whitespace, parses the longest valid
/// float prefix (ignoring trailing garbage), and panics on invalid input just
/// as `std::stof` throws `std::invalid_argument`.
fn stof(s: &str) -> f32 {
    let t = s.trim_start();
    if let Ok(v) = t.parse::<f32>() {
        return v;
    }

    let bytes = t.as_bytes();
    let mut end = 0;

    // Optional sign.
    if end < bytes.len() && (bytes[end] == b'+' || bytes[end] == b'-') {
        end += 1;
    }
    // Integer and fractional digits with an optional single dot.
    let mut seen_digit = false;
    let mut seen_dot = false;
    while end < bytes.len() {
        match bytes[end] {
            b'0'..=b'9' => {
                seen_digit = true;
                end += 1;
            }
            b'.' if !seen_dot => {
                seen_dot = true;
                end += 1;
            }
            _ => break,
        }
    }
    // Optional exponent, only if the mantissa had digits.
    if seen_digit && end < bytes.len() && (bytes[end] == b'e' || bytes[end] == b'E') {
        let mut eend = end + 1;
        if eend < bytes.len() && (bytes[eend] == b'+' || bytes[eend] == b'-') {
            eend += 1;
        }
        let exp_start = eend;
        while eend < bytes.len() && bytes[eend].is_ascii_digit() {
            eend += 1;
        }
        if eend > exp_start {
            end = eend;
        }
    }

    if !seen_digit {
        // std::stof also accepts inf/infinity/nan (case-insensitive).
        let lower = t.to_ascii_lowercase();
        let neg = lower.starts_with('-');
        let body = lower.trim_start_matches(['+', '-']);
        for (name, val) in [
            ("infinity", f32::INFINITY),
            ("inf", f32::INFINITY),
            ("nan", f32::NAN),
        ] {
            if body.starts_with(name) {
                return if neg { -val } else { val };
            }
        }
        panic!("std::stof: no conversion could be performed");
    }

    t[..end].parse::<f32>().expect("scanned prefix is a valid float")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut y: f32 = 0.5;
    let mut u: f32 = 0.2;
    let mut v: f32 = 0.3;

    if args.len() > 3 {
        y = stof(&args[1]);
        u = stof(&args[2]);
        v = stof(&args[3]);
    }

    let yuv = Yuv::new(y, u, v);
    let rgb = ColorConverter::yuv_to_rgb(&yuv);
    let hsl = ColorConverter::rgb_to_hsl(&rgb);

    println!(
        "{} {} {} {} {} {}",
        fmt_g(rgb.r),
        fmt_g(rgb.g),
        fmt_g(rgb.b),
        fmt_g(hsl.h),
        fmt_g(hsl.s),
        fmt_g(hsl.l)
    );
}

