    let diff = g - b;
    let h_a = (diff / d + 6.0) * 60.0;
    let h_b = diff / d * 60.0 + 360.0;
    let h_c = 60.0 * diff / d + 360.0;
    let h_d = (diff + 6.0 * d) / d * 60.0;
    let h_e = (diff + 6.0 * d) * 60.0 / d;
    println!("f32 a={:.9e} b={:.9e} c={:.9e} d={:.9e} e={:.9e}", h_a, h_b, h_c, h_d, h_e);
    // f64 versions from f32 inputs
    let (r6, g6, b6) = (r as f64, g as f64, b as f64);
    let d6 = r6 - g6;
    let h6 = ((g6 - b6) / d6 + 6.0) * 60.0;
    println!("f64 from f32 inputs: {:.10}", h6);
    // threshold: cpp printed 340.022 -> h in [340.0215, 340.0225)
    // try perturbing r,g,b by one ulp each and see which combos land below 340.0225
    let pert = |x: f32, k: i32| -> f32 {
        let bits = x.to_bits() as i64 + k as i64;
        f32::from_bits(bits as u32)
    };
    for kr in -1..=1 { for kg in -1..=1 { for kb in -1..=1 {
        let rr = pert(r, kr); let gg = pert(g, kg); let bb = pert(b, kb);
        let d6 = (rr as f64) - (gg as f64);
        let h = (((gg as f64) - (bb as f64)) / d6 + 6.0) * 60.0;
        if h < 340.0225 {
            println!("kr={} kg={} kb={} -> {:.10}", kr, kg, kb, h);
        }
    }}}
}
