        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let mut s = format!("{:.*}", (P - 1 - exp) as usize, v);
        if s.contains('.') { while s.ends_with('0') { s.pop(); } if s.ends_with('.') { s.pop(); } }
        s
    }
}

#[derive(Clone, Debug)]
enum T { L(u8), B(u8, Box<T>, Box<T>) } // L: 0=D,1=C,2=A,3=S ; B: op 0..3 (+,-,*,/)

fn ev(t: &T, v: &[f32;4]) -> f32 {
    match t {
        T::L(i) => v[*i as usize],
        T::B(op, a, b) => {
            let (x, y) = (ev(a, v), ev(b, v));
            match op { 0 => x + y, 1 => x - y, 2 => x * y, _ => x / y }
        }
    }
}
fn ev64(t: &T, v: &[f64;4]) -> f64 {
    match t {
        T::L(i) => v[*i as usize],
        T::B(op, a, b) => {
            let (x, y) = (ev64(a, v), ev64(b, v));
            match op { 0 => x + y, 1 => x - y, 2 => x * y, _ => x / y }
        }
    }
}
fn show(t: &T) -> String {
    match t {
        T::L(i) => ["D","C","A","S"][*i as usize].to_string(),
        T::B(op, a, b) => format!("({}{}{})", show(a), ["+","-","*","/"][*op as usize], show(b)),
    }
}

fn main() {
    // build all trees with up to 7 nodes
    let mut by_size: HashMap<usize, Vec<T>> = HashMap::new();
    let mut base = Vec::new();
    for l in 0..4 { base.push(T::L(l)); }
    by_size.insert(1, base);
    for size in 3..=7 step 2 {
        let mut v = Vec::new();
        for ls in (1..size).step(2) {
            let rs = size - 1 - ls;
            if rs < 1 { continue; }
            let (Some(lt), Some(rt)) = (by_size.get(&ls), by_size.get(&rs)) else { continue };
            for a in lt { for b in rt { for op in 0..4u8 {
                v.push(T::B(op, Box::new(a.clone()), Box::new(b.clone())));
            }}}
        }
        by_size.insert(size, v);
    }
    let mut all: Vec<T> = Vec::new();
    for size in [1usize, 3, 5, 7] { all.extend(by_size.get(&size).unwrap().iter().cloned()); }
    println!("total trees: {}", all.len());

    // failing cases under tree0: gather (D,C,A,neg, cpp_h_string) — only h matters
    let corpus = fs::read_to_string("/tmp/corpus.txt").unwrap();
    let cpp = fs::read_to_string("/tmp/cpp_out.txt").unwrap();
    let mut cases: Vec<([f32;4], String)> = Vec::new(); // (D,C,A), cpp_h
    let mut allcases: Vec<([f32;4], String)> = Vec::new();
    for (ln, out) in corpus.lines().zip(cpp.lines()) {
        let mut it = ln.split_whitespace();
        let y: f32 = it.next().unwrap().parse().unwrap();
        let u: f32 = it.next().unwrap().parse().unwrap();
        let v: f32 = it.next().unwrap().parse().unwrap();
        let r = y + 1.14f32 * v;
        let g = y - 0.395f32 * u - 0.581f32 * v;
        let b = y + 2.032f32 * u;
        let mn = r.min(g).min(b); let mx = r.max(g).max(b);
        if mx == mn { continue; }
        let d = mx - mn;
        let (diff, adj) = if mx == r { (g - b, if g < b { 6.0f32 } else { 0.0 }) }
            else if mx == g { (b - r, 2.0) } else { (r - g, 4.0) };
        let cpp_h = out.split_whitespace().nth(3).unwrap().to_string();
        let h0 = (diff / d + adj) * 60.0;
        let entry = ([diff, d, adj, 60.0], cpp_h);
        if fmt_g(h0) != entry.1 { cases.push(entry.clone()); }
        allcases.push(entry);
    }
    println!("failing cases: {}", cases.len());

    // semantic filter: |tree64 - true| / |true| < 1e-6 on a few sample cases; then f32 match on failing cases
    let mut survivors = Vec::new();
    'outer: for t in &all {
        for (v, _) in cases.iter().take(5).chain(allcases.iter().take(5)) {
            let v64 = [v[0] as f64, v[1] as f64, v[2] as f64, v[3] as f64];
            let truth = (v64[0]/v64[1] + v64[2]) * 60.0;
            let got = ev64(t, &v64);
            if (got - truth).abs() > 1e-6 * truth.abs().max(1.0) { continue 'outer; }
        }
        let mut ok = true;
        for (v, ch) in &cases {
            if fmt_g(ev(t, v)) != *ch { ok = false; break; }
        }
        if ok { survivors.push(t); }
    }
    println!("survivors matching all failing cases:");
    for t in &survivors { println!("  {}", show(t)); }
    // verify survivors on ALL cases
    for t in &survivors {
        let mut fail = 0;
        for (v, ch) in &allcases {
            if fmt_g(ev(t, v)) != *ch { fail += 1; }
        }
        println!("tree {} : {}/{} fails on all cases", show(t), fail, allcases.len());
    }
}
