        for (v, ch) in &cases {
            if fmt_g(ev(t, v)) != *ch { ok = false; break; }
        }
        if ok { survivors.push(t); }
    }
    println!("survivors matching all failing cases:");
    for t in &survivors { println!("  {}", show(t)); }
    // verify survivors on ALL cases
    for t in &survivors {
        let mut fail = 0;
        for (v, ch) in &allcases {
            if fmt_g(ev(t, v)) != *ch { fail += 1; }
        }
        println!("tree {} : {}/{} fails on all cases", show(t), fail, allcases.len());
    }
