use std::fs;
fn fmt_g(value: f32) -> String {
    let v = value as f64;
    if v == 0.0 { return if v.is_sign_negative() { "-0".into() } else { "0".into() }; }
    const P: i32 = 6;
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= P {
        let mut mant = sci[..epos].to_string();
        if mant.contains('.') { while mant.ends_with('0') { mant.pop(); } if mant.ends_with('.') { mant.pop(); } }
        format!("{}e{}{:02}", mant, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let mut s = format!("{:.*}", (P - 1 - exp) as usize, v);
        if s.contains('.') { while s.ends_with('0') { s.pop(); } if s.ends_with('.') { s.pop(); } }
        s
    }
}
fn pert(x: f32, k: i32) -> f32 { f32::from_bits((x.to_bits() as i64 + k as i64) as u32) }
fn main() {
    let corpus = fs::read_to_string("/tmp/corpus.txt").unwrap();
    let cpp = fs::read_to_string("/tmp/cpp_out.txt").unwrap();
    for (ln, out) in corpus.lines().zip(cpp.lines()) {
        let mut it = ln.split_whitespace();
        let y: f32 = it.next().unwrap().parse().unwrap();
        let u: f32 = it.next().unwrap().parse().unwrap();
        let v: f32 = it.next().unwrap().parse().unwrap();
        let r = y + 1.14f32 * v;
        let g = y - 0.395f32 * u - 0.581f32 * v;
        let b = y + 2.032f32 * u;
        let compute = |r: f32, g: f32, b: f32| -> String {
            let mn = r.min(g).min(b); let mx = r.max(g).max(b);
            let l = (mx + mn) / 2.0;
            let (h, s);
            if mx == mn { h = 0.0; s = 0.0; } else {
                let d = mx - mn;
                s = if l <= 0.5 { d / (mx + mn) } else { d / (2.0 - mx - mn) };
                h = if mx == r { ((g - b)/d + if g < b {6.0} else {0.0}) * 60.0 }
                    else if mx == g { ((b - r)/d + 2.0) * 60.0 }
                    else { ((r - g)/d + 4.0) * 60.0 };
            }
            format!("{} {} {} {} {} {}", fmt_g(r), fmt_g(g), fmt_g(b), fmt_g(h), fmt_g(s), fmt_g(l))
        };
        if compute(r, g, b) != out {
            let mut sols = Vec::new();
            for kr in -3i32..=3 { for kg in -3i32..=3 { for kb in -3i32..=3 {
                if kr == 0 && kg == 0 && kb == 0 { continue; }
                if compute(pert(r,kr), pert(g,kg), pert(b,kb)) == *out {
                    sols.push((kr, kg, kb));
                }
            }}}
            sols.sort_by_key(|s| s.0.abs() + s.1.abs() + s.2.abs());
            sols.truncate(4);
            println!("[{}] cpp={} sols={:?}", ln, out, sols);
        }
    }
}
