        0 => (y + 1.14f32 * v, y - 0.395f32 * u - 0.581f32 * v, y + 2.032f32 * u),
        1 => ((y as f64 + 1.14f64 * v as f64) as f32,
              (y as f64 - 0.395f64 * u as f64 - 0.581f64 * v as f64) as f32,
              (y as f64 + 2.032f64 * u as f64) as f32),
        _ => unreachable!(),
    }
}
// stage-2 model on f32 r,g,b; returns h as f32 (possibly via f64 paths)
fn stage2(r: f32, g: f32, b: f32, m: u32) -> (f32, f32, f32) {
    let mn = r.min(g).min(b); let mx = r.max(g).max(b);
    let l = (mx + mn) / 2.0;
    if mx == mn { return (0.0, 0.0, l); }
    let d = mx - mn;
