    let h = match m {
        0 => (q + adj) * 60.0,
        1 => (((diff as f64) / (d as f64) + adj as f64) * 60.0) as f32,   // f64 all
        2 => (((diff as f64) / (mx as f64 - mn as f64) + adj as f64) * 60.0) as f32, // f64 exact delta
        3 => ((q as f64 + adj as f64) * 60.0) as f32,                     // f32 div, f64 rest
        4 => (diff + adj * d) / d * 60.0,
        5 => { // f64 quotient kept f64, +adj *60 in f64, no cast till print... emulate via f64 bits
            (((diff as f64) / (d as f64) + adj as f64) * 60.0) as f32
        }
        _ => unreachable!(),
    };
    (h, s, l)
}
